RULES_VERSION='0.1-prototype'
def assess_rules(project):
 s=project.get('site',{}); p=project.get('program',{})
 bw=float(s.get('width_m',0))-float(s.get('setbacks',{}).get('left',0))-float(s.get('setbacks',{}).get('right',0)); bd=float(s.get('depth_m',0))-float(s.get('setbacks',{}).get('front',0))-float(s.get('setbacks',{}).get('rear',0))
 return {'registry_version':RULES_VERSION,'assessments':[{'rule_id':'SITE-001','category':'envelope','status':'PASS' if bw>0 and bd>0 else 'REVIEW','message':'Preliminary envelope only; verify authoritative zoning source.','source':'SOURCE_REQUIRED'},{'rule_id':'SITE-002','category':'parking','status':'REVIEW','message':f"Program requests {int(p.get('parking',2))} parking space(s); verify applicable requirement.",'source':'SOURCE_REQUIRED'},{'rule_id':'SITE-003','category':'orientation','status':'PARTIAL','message':f"North reference captured at {s.get('north_deg',0)} degrees; no solar compliance simulation.",'source':'SOURCE_REQUIRED'},{'rule_id':'LIFE-001','category':'life_safety','status':'REVIEW','message':'Project-specific egress/life-safety verification required.','source':'SOURCE_REQUIRED'},{'rule_id':'ACC-001','category':'accessibility','status':'REVIEW','message':'Project-specific accessibility verification required.','source':'SOURCE_REQUIRED'}],'compliance_statement':'Prototype decision support only; not a code-compliance certificate.'}
